import (
	"fmt"
	"os"
	"strings"

	"github.com/prestontallen/ai-devboard/worklog/internal/devboard"
	"github.com/prestontallen/ai-devboard/worklog/internal/migrate"
	"github.com/prestontallen/ai-devboard/worklog/internal/model"
	"github.com/prestontallen/ai-devboard/worklog/internal/projection"
	"github.com/prestontallen/ai-devboard/worklog/internal/reindex"
	"github.com/prestontallen/ai-devboard/worklog/internal/store"
	"github.com/prestontallen/ai-devboard/worklog/internal/store/sqlitestore"
)

// nextRank is the Rank a newly created ticket must carry: one past the
// highest rank among live tickets, so it renders at the END of its
// section.
//
// Leaving it at the zero value is not "unranked" — it is the literal
// rank of whichever ticket sits first in WORK.md, because convert
// numbers document position from zero (convert/workmd.go:73). A new
// ticket defaulting to 0 therefore *ties* the first ticket, and
// Tickets() breaks that tie with `ORDER BY rank, slug` — so the new
// ticket silently sorts by alphabetical luck instead of landing where
// the human put it. Observed live: a ticket added on 2026-09-03 tied
// adb-research-mode at rank 0 and won the slug comparison, jumping to
// the top of ## Now.
//
// Archived tickets are excluded: their Rank is a position within an
// archive month, a different numbering space that says nothing about
// where a live ticket belongs.
func nextRank(s store.Store) (int, error) {
	tickets, err := s.Tickets()
	if err != nil {
		return 0, err
	}
	max := -1
	for _, t := range tickets {
		if !t.Archived && t.Rank > max {
			max = t.Rank
		}
	}
	return max + 1, nil
}

// nextRosterRank is nextRank for an epic's child roster. Same collision,
// one level down: RosterRank is assigned only by convert (convert.go:161,
// :181), so a child added through the CLI defaults to 0, ties the epic's
// first child, and is ordered against it by slug.
func nextRosterRank(s store.Store, parent store.ID) (int, error) {
	kids, err := s.Children(parent)
	if err != nil {
		return 0, err
	}
	return nextRosterRankOf(kids), nil
}

// nextRosterRankOf is nextRosterRank for a caller that already holds the
// roster, so the only copy of the "one past the highest" rule lives here.
func nextRosterRankOf(kids []*store.Ticket) int {
	max := -1
	for _, k := range kids {
		if k.RosterRank > max {
			max = k.RosterRank
		}
	}
	return max + 1
}

// requireAdopted refuses before opening a store that does not exist yet.
//
// Without this the machine gets the wrong error entirely: sqlitestore.Open
// CREATES the database when the path is absent, so the verb proceeds
// against an empty store, Render emits a WORK.md the corpus does not
// match, and EditedIn reports every file as "edited by hand" — on a
// machine where nobody edited anything. Worse, the advice that refusal
// gives ("they are build outputs; the store is the source") is actively
// dangerous against an empty store: following it means deleting the
// corpus. Say what is actually true instead, and name the command.
func requireAdopted(dataDir string) error {
	if _, err := os.Stat(migrate.OutputPath(dataDir)); err == nil {
		return nil
	} else if !os.IsNotExist(err) {
		return fmt.Errorf("opening store: %w", err)
	}
	return errWithExit(1,
		"this machine has not adopted the store yet — no database at %s\nrun `worklog adopt` to preview the adoption, then `worklog adopt --commit`",
		migrate.OutputPath(dataDir))
}

// storeSession is one write verb's open store handle plus the layout it
// renders into — the shared plumbing every ticket-shaped store-backed
// write verb (start/done/edit/pr/link/note/wait/add/import) opens once,
// mutates a *store.Ticket (or several) against, and commits. The
// task<sub> family (task_store.go) predates this helper and keeps its
// own inline version; not worth touching already-shipped, tested code
// to unify the ~15 lines of overlap.
type storeSession struct {
	s      store.Store
	layout projection.Layout
	wd     model.Workdir
}

// openStoreForWrite opens the store and refuses up front if any
// projection under wd/devboard has been hand-edited since the last
// render — the M3b policy: refuse before mutating, never after, since a
// render destroys whatever a human typed by hand.
func openStoreForWrite(wd model.Workdir) (*storeSession, error) {
	dataDir, err := storeDataDir()
	if err != nil {
		return nil, err
	}
	if err := requireAdopted(dataDir); err != nil {
		return nil, err
	}
	s, err := sqlitestore.Open(migrate.OutputPath(dataDir))
	if err != nil {
		return nil, fmt.Errorf("opening store: %w", err)
	}
	layout := projection.Layout{WorklogDir: wd.Root, DevboardDir: devboard.DataDir()}

	edited, err := projection.EditedIn(s, layout)
	if err != nil {
		s.Close()
		return nil, fmt.Errorf("checking projections: %w", err)
	}
	if len(edited) > 0 {
		s.Close()
		return nil, errWithExit(1,
			"refusing to write — these projections were edited by hand and a re-render would discard the changes:\n  %s\nreconcile them first (they are build outputs; the store is the source)",
			strings.Join(edited, "\n  "))
	}
	return &storeSession{s: s, layout: layout, wd: wd}, nil
}

func (ss *storeSession) close() { ss.s.Close() }

// commit persists t and synchronously re-renders every projection plus
// INDEX.md, so the dashboard and session-start hook see the write before
// this process exits (contract criterion 3). Unlike the task<sub> family,
// which never touches an indexed field, these verbs can change
// title/section/repo/tags, so INDEX.md is regenerated every time.
func (ss *storeSession) commit(t *store.Ticket) error {
	if err := ss.s.PutTicket(t); err != nil {
		return err
	}
	return ss.render()
}

// commitFeedback persists e and re-renders — FEEDBACK.md isn't one of
// INDEX.md's four sections (ticket/tag/repo/archive-month), so no
// reindex is needed here.
func (ss *storeSession) commitFeedback(e *store.FeedbackEntry) error {
	if err := ss.s.PutFeedback(e); err != nil {
		return err
	}
	return projection.RenderTo(ss.s, ss.layout)
}

func (ss *storeSession) render() error {
	if err := projection.RenderTo(ss.s, ss.layout); err != nil {
		return fmt.Errorf("rendering projections: %w", err)
	}
	if _, err := reindex.Run(ss.wd, reindex.Inputs{}); err != nil {
		return fmt.Errorf("regenerating INDEX.md: %w", err)
	}
	return nil
}

// ensureBoardTracked replicates the one create-if-missing devboard hook
// the legacy write surface had (devboard.OnStart — done/pr/link's hooks
// all no-op on a missing entry, matching devboard.Find's contract). A
// ticket that has never been on the board gets BoardTracked, its session
// (for the dashboard's resume button — dev-context documents this as
// automatic on start), branch, and repo path; an already-tracked ticket
// only gets its repo path self-healed, same as legacy. declaredRepo is
// the ticket's own canonical Repo, used only to resolve a filesystem
// root when RepoPath is empty or has gone away.
func ensureBoardTracked(t *store.Ticket, declaredRepo string) {
	if t.BoardTracked {
		if t.RepoPath == "" || !dirExists(t.RepoPath) {
			if root := devboard.RepoRootFor(declaredRepo); root != "" {
				t.RepoPath = root
			}
		}
		return
	}
	if !devboard.Enabled() {
		return // devboard is opt-in by dir presence; a first tracking is a no-op, not a create
	}
	t.BoardTracked = true
	if s := os.Getenv("CLAUDE_CODE_SESSION_ID"); s != "" {
		t.Session = s
	}
	if b := devboard.GitBranch(); b != "" {
		t.Branch = b
	}
	if root := devboard.RepoRootFor(declaredRepo); root != "" {
		t.RepoPath = root
	}
}

// ensureParentBoardTracked replicates legacy's devboardSyncEpic, called on
// every child start/resume/done: a child's parent epic never goes through
// its own start (epics can't occupy ## Now), so nothing else ever
// board-tracks it. Without this, an epic's own file is never created and
// children with nowhere to nest never render. No-ops for a standalone
// ticket (t.ParentID == "") or if the parent lookup fails — a dangling
// ParentID is reported by the caller's own checks, not silently patched
// here.
func ensureParentBoardTracked(ss *storeSession, t *store.Ticket) error {
	if t.ParentID == "" {
		return nil
	}
	parent, err := ss.s.Ticket(t.ParentID)
	if err != nil {
		return nil
	}
	ensureBoardTracked(parent, parent.Repo)
	return ss.s.PutTicket(parent)
}

// clearBoardTracked is untrack's store-side half. Render only ever writes
// the files it expects (every BoardTracked, non-child ticket); it never
// prunes a file that fell out of that set, so deleting a task file alone
// would leave it recreated on the next write that happens to re-render.
// No-op (not an error) when id doesn't resolve to a store ticket — a bare
// producer file (no worklog: join key) has nothing in the store to clear,
// and the caller deletes the file directly in that case.
func clearBoardTracked(wd model.Workdir, id string) error {
	ss, err := openStoreForWrite(wd)
	if err != nil {
		return err
	}
	defer ss.close()
	t, err := ss.s.TicketBySlug(id)
	if store.IsNotFound(err) {
		return nil
	}
	if err != nil {
		return err
	}
	t.BoardTracked = false
	return ss.commit(t)
}

func dirExists(p string) bool {
	if p == "" {
		return false
	}
	fi, err := os.Stat(p)
	return err == nil && fi.IsDir()
}

// ticketBySlugOrErr resolves slug to a *store.Ticket, mapping a
// not-found lookup to notFoundErr (typically a package's own
// ErrIDNotFound sentinel) so callers keep their existing error-mapping
// switch statements unchanged between the legacy and store paths.
func (ss *storeSession) ticketBySlugOrErr(slug string, notFoundErr error) (*store.Ticket, error) {
	t, err := ss.s.TicketBySlug(slug)
	if store.IsNotFound(err) {
		return nil, fmt.Errorf("%w: %q", notFoundErr, slug)
	}
	if err != nil {
		return nil, err
	}
	return t, nil
}

// Package cli wires up cobra commands for the worklog CLI.
package cli

import (
	"fmt"
	"os"

	"github.com/charmbracelet/log"
	"github.com/spf13/cobra"

	"github.com/prestontallen/ai-devboard/worklog/internal/freeze"
	"github.com/prestontallen/ai-devboard/worklog/internal/model"
)

// freezeExemptCommands are the top-level commands that keep running while a
// write freeze is held — everything else is refused. This is a default-deny
// list on purpose: a new write verb added later without an entry here is
// blocked during a freeze by default, rather than silently allowed.
var freezeExemptCommands = map[string]bool{
	"validate":  true,
	"status":    true,
	"standup":   true,
	"tui":       true,
	"search":    true,
	"summarize": true,
	"verify":    true,
	"migrate":   true,
	"install":   true,
	"hook":      true,
	"serve":     true,
	"freeze":    true,
	// adopt acquires the freeze itself for its own write window, so it
	// must not be blocked by the freeze it is about to take.
	"adopt": true,
}

// topLevelName returns the name of cmd's ancestor that is a direct child of
// the root command, or "" for the bare `worklog` invocation (root itself),
// which runs the read-only default status action.
func topLevelName(cmd *cobra.Command) string {
	root := cmd.Root()
	if cmd == root {
		return ""
	}
	node := cmd
	for node.Parent() != root {
		node = node.Parent()
	}
	return node.Name()
}

// global state populated by root persistent flags.
var (
	flagDir    string
	logger     *log.Logger
	rootCmd    *cobra.Command
	versionStr string // set by main via SetVersion

	// raw build-stamp parts, exposed for the installer's staleness check
	// (comparing the joined display string is how drift bugs happen).
	buildVersion = "dev"
	buildCommit  = "none"
	buildDate    = "unknown"
)

// SetVersion wires the build-time version string (injected via ldflags) into
// the root command before Execute is called.
func SetVersion(version, commit, date string) {
	buildVersion, buildCommit, buildDate = version, commit, date
	versionStr = version + " (" + commit + ", " + date + ")"
}

// BuildCommit returns the raw commit stamp (e.g. "8f6deba" or
// "8f6deba-dirty"), for rev comparison against a repo checkout.
func BuildCommit() string { return buildCommit }

// BuildVersion returns the raw version stamp (e.g. "0.2.0-dev" or a
// release tag like "v0.3.0").
func BuildVersion() string { return buildVersion }

// resolveWorkdir reads the --dir flag, falling back to $WORKLOG_DIR, then to
// model.NewWorkdir's default.
func resolveWorkdir() (model.Workdir, error) {
	dir := flagDir
	if dir == "" {
		dir = os.Getenv("WORKLOG_DIR")
	}
	return model.NewWorkdir(dir)
}

// newRoot constructs the root cobra command and attaches all subcommands.
func newRoot() *cobra.Command {
	cmd := &cobra.Command{
		Use:     "worklog",
		Args:    cobra.NoArgs,
		Version: versionStr,
		Short:   "Personal worklog: cross-session task journal with cap, archive, and index",
		Long: `worklog is the canonical tool for Preston's personal worklog system.

It reads and (eventually) writes a small markdown corpus at
$HOME/.local/share/worklog/ — a front-page WORK.md, a per-month archive, an
INDEX.md spine, and per-epic notes files. The tool replaces a set of bash
scripts that handled validation and skill deployment.`,
		SilenceUsage:  true,
		SilenceErrors: true,
		// Default action: run "status" so `worklog` alone shows the front page.
		// The bare invocation is the human path; agents should call
		// `worklog status --json` explicitly when they need machine-readable
		// output.
		RunE: func(cmd *cobra.Command, args []string) error {
			return runStatus(cmd, false)
		},
		PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
			if freezeExemptCommands[topLevelName(cmd)] {
				return nil
			}
			wd, err := resolveWorkdir()
			if err != nil {
				return err
			}
			frozen, info, err := freeze.Check(wd.Root)
			if err != nil {
				return err
			}
			if !frozen {
				return nil
			}
			return freeze.RefusalError(info)
		},
	}

	cmd.PersistentFlags().StringVar(&flagDir, "dir", "",
		"worklog data directory (default $WORKLOG_DIR or ~/.local/share/worklog)")

	cmd.AddCommand(
		newValidateCmd(),
		newStatusCmd(),
		newStandupCmd(),
		newTUICmd(),
		newAddCmd(),
		newImportCmd(),
		newStartCmd(),
		newEditCmd(),
		newDoneCmd(),
		newPrCmd(),
		newLinkCmd(),
		newReindexCmd(),
		newSearchCmd(),
		newServeCmd(),
		newSummarizeCmd(),
		newFeedbackCmd(),
		newNoteCmd(),
		newWaitCmd(),
		newTaskCmd(),
		newHookCmd(),
		newInstallCmd(),
		newMigrateCmd(),
		newVerifyCmd(),
		newAdoptCmd(),
		newFreezeCmd(),
	)
	return cmd
}

// Execute is the entrypoint called from main. It returns a process exit code.
func Execute() int {
	logger = log.New(os.Stderr)
	logger.SetReportTimestamp(false)
	logger.SetLevel(log.InfoLevel)

	rootCmd = newRoot()
	if err := rootCmd.Execute(); err != nil {
		// Some subcommands return a typed error to set a non-default exit
		// code; honor those first.
		if ec, ok := err.(exitCoder); ok {
			fmt.Fprintln(os.Stderr, ec.Error())
			return ec.ExitCode()
		}
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	return 0
}

// exitCoder lets subcommands signal a specific process exit code via error.
type exitCoder interface {
	error
	ExitCode() int
}

type codedError struct {
	code int
	msg  string
}

func (e *codedError) Error() string { return e.msg }
func (e *codedError) ExitCode() int { return e.code }
func errWithExit(code int, format string, a ...any) *codedError {
	return &codedError{code: code, msg: fmt.Sprintf(format, a...)}
}

