	if err != nil {
		return nil, "", nil, err
	}
	if child == "" {
		return nil, "", nil, errWithExit(64,
			"task: --id %q is an epic; pass --child <id> (children: %s)",
			t.Slug, strings.Join(storeChildIDs(kids), ", "))
	}
